#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ks(n);
    vector<vector<pair<int,int>>> orig(n);
    int totalCells = 0;
    for(int i = 0; i < n; i++){
        cin >> ks[i];
        orig[i].resize(ks[i]);
        for(int j = 0; j < ks[i]; j++){
            cin >> orig[i][j].first >> orig[i][j].second;
        }
        totalCells += ks[i];
    }

    // Transform: first flip (f=1 means x=-x), then rotate r times 90° CCW
    // CCW rotation: (x,y) -> (-y,x)
    auto transform = [&](const vector<pair<int,int>>& cells, int f, int r) -> vector<pair<int,int>> {
        vector<pair<int,int>> res;
        for(auto [x,y] : cells){
            int nx = x, ny = y;
            if(f) nx = -nx;
            for(int q = 0; q < r; q++){
                int tmp = -ny;
                ny = nx;
                nx = tmp;
            }
            res.push_back({nx, ny});
        }
        // Normalize to min 0
        int minx = INT_MAX, miny = INT_MAX;
        for(auto [x,y] : res){ minx=min(minx,x); miny=min(miny,y); }
        for(auto& [x,y] : res){ x-=minx; y-=miny; }
        return res;
    };

    struct Ori { vector<pair<int,int>> cells; int w,h,f,r; };
    vector<vector<Ori>> allOris(n);
    for(int i = 0; i < n; i++){
        set<vector<pair<int,int>>> seen;
        for(int f = 0; f < 2; f++){
            for(int r = 0; r < 4; r++){
                auto tc = transform(orig[i], f, r);
                sort(tc.begin(), tc.end());
                if(seen.insert(tc).second){
                    int w=0,h=0;
                    for(auto [x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                    allOris[i].push_back({tc,w,h,f,r});
                }
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){
        return ks[a]>ks[b]||(ks[a]==ks[b]&&allOris[a].size()<allOris[b].size());
    });

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&](){return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();};

    int bestArea=INT_MAX, bestW=0, bestH=0;
    struct Pl{int x,y,r,f;};
    vector<Pl> bestPl(n);

    double sq=sqrt((double)totalCells);
    for(int W=max(1,(int)(sq*0.5)); W<=max((int)(sq*3),totalCells+10) && elapsed()<9.0; W++){
        int maxH=totalCells/max(1,W)+n*10+10;
        if((long long)W*1>bestArea) continue;
        vector<int> hmap(W,0);
        vector<vector<bool>> grid(W,vector<bool>(maxH,false));
        vector<Pl> pl(n);
        int curH=0; bool fail=false;
        for(int idx=0;idx<n;idx++){
            int pi=order[idx];
            int bs=INT_MAX,bx=-1,by=-1,boi=-1;
            for(int oi=0;oi<(int)allOris[pi].size();oi++){
                auto&o=allOris[pi][oi];
                if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){
                    int my=0;
                    for(auto&[cx,cy]:o.cells) my=max(my,hmap[x+cx]-cy);
                    if(my<0)my=0;
                    int top=0;
                    for(auto&[cx,cy]:o.cells) top=max(top,my+cy+1);
                    if(top>maxH)continue;
                    bool ok=true;
                    for(auto&[cx,cy]:o.cells) if(grid[x+cx][my+cy]){ok=false;break;}
                    if(ok){int s=top*10000+x;if(s<bs){bs=s;bx=x;by=my;boi=oi;}}
                }
            }
            if(bx<0){fail=true;break;}
            auto&o=allOris[pi][boi];
            for(auto&[cx,cy]:o.cells){grid[bx+cx][by+cy]=true;hmap[bx+cx]=max(hmap[bx+cx],by+cy+1);curH=max(curH,by+cy+1);}
            pl[pi]={bx,by,o.r,o.f};
        }
        if(fail)continue;
        int area=W*curH;
        if(area<bestArea){bestArea=area;bestW=W;bestH=curH;bestPl=pl;}
    }
    if(bestArea==INT_MAX){bestW=totalCells;bestH=1;int cx=0;for(int i=0;i<n;i++){bestPl[i]={cx,0,0,0};cx+=ks[i];}bestW=cx;bestH=1;}
    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
